SELECT count() AS days_traded, sum(n_quotes) AS total_quotes, min(bp_min) AS lowest_bid, max(bp_max) AS highest_bid, min(ap_min) AS lowest_ask, max(ap_max) AS highest_ask, sum(spread_sum) / sum(n_quotes) AS avg_spread, sum(bs_sum) AS total_bid_volume, sum(as_sum) AS total_ask_volume FROM quotes_daily WHERE sym = 'AAPL' LIMIT 1000000 SETTINGS max_threads=59,enable_parallel_replicas=0,max_parallel_replicas=1,use_query_cache=0,log_queries=1,log_query_settings=1,log_queries_probability=1,log_queries_min_query_duration_ms=0,max_execution_time=30,timeout_before_checking_execution_speed=0,max_rows_to_read=1000000000,max_bytes_to_read=100000000000,max_result_rows=1000000,result_overflow_mode='throw',log_comment='reader-scaling-20261011T101134Z-pilot' FORMAT Null
